 static int postureCommand(String text){String t=clean(text);if(excluded(t)||has(t,"？","?","ませんか","と呼","という","と言った"))return -1;if(t.matches("(?s).*(座って|すわって|お座り|腰掛けて|腰かけて|腰を下ろして)(ください|くれる|ね|よ|ほしい)?[。！!\\s]*$"))return 1;if(t.matches("(?s).*(立って|立ち上がって)(ください|くれる|ね|よ|ほしい)?[。！!\\s]*$"))return 0;return -1;}
 static boolean legCommand(String text){String t=clean(text);return !excluded(t)&&!has(t,"ないで","しない","と言った","と言って","彼女が","彼が")&&has(t,"脚を組み替えて","足を組み替えて","脚を組みかえて","足を組みかえて","足を組み換えて","脚を組み換えて","脚を組んで","足を組んで");}
 static int everydayCommand(String text){String t=clean(text);if(excluded(t)||has(t,"ないで","とは","と言った"))return -1;if(has(t,"耳たぶを触って","イヤリングを触って","耳飾りを触って"))return 1;if(has(t,"手を差し出して","手を差し伸べて","手を伸ばして"))return 2;if(has(t,"手招きして"))return 3;return -1;}
 void neutralFace(){expression=-1;restFace=0;restFacePinned=false;explicitExpression=false;}
 static boolean waveCommand(String text){String t=clean(text).replaceFirst("^ロキ[、, :：]*","");return t.matches("(?:手を振って|手をふって)(?:ください|みて|くれる|ね|よ)?[。！!\\s]*");}
 static final class PreviewState {final Snapshot current,last,previous;final String command;final long time;final int repair;PreviewState(EmbodiedScenePolicy p){current=new Snapshot(p);last=p.lastVisual;previous=p.previousVisual;command=p.lastCommand;time=p.lastCommandAt;repair=p.pendingRepair;}}
