 boolean carries(String text){if(VisualRepairIntent.kind(text)!=0)return canReplay()||canUndo();if(stable()&&!FullBodyConversationContinuity.end(text)&&!FullBodyAffectionCue.stop(text))return true;if(FullBodyConversationContinuity.topic(text)||FullBodyConversationContinuity.end(text)||FullBodyAffectionCue.stop(text))return false;return (RestPoseIntent.kind(text)!=RestPoseIntent.NONE||ShyFidgetMotion.request(text)||scene==SHY_FIDGET||scene==RELAXED||scene==LEG_CROSS||scene==OVERHEAD||posture>=0)&&(RestPoseIntent.kind(text)!=RestPoseIntent.NONE||ShyFidgetMotion.request(text)||PoisedMotionPolicy.expression(text)>=0||PoisedMotionPolicy.command(text)>=0||PoisedMotionPolicy.relaxed(text,scene==OVERHEAD||scene==RELAXED&&pose>=2)>=0||has(text,"そのまま","ありがとう","いいね","続けて","もう少し"));}
