 void preview(int kind,int index,long now){fidgetAt=kind==SHY_FIDGET?now:-1;expression=-1;explicitExpression=false;scene=kind;pose=Math.max(0,Math.min(7,index));at=now;cycle=false;kissType=0;restAuthority=kind==RELAXED;if(kind==RELAXED)posture=index<2?1:0;if(kind==LEG_CROSS)posture=1;}
