 private int pendingRepair;private Snapshot lastVisual,previousVisual;private String lastCommand="";private long lastCommandAt;
 static final class Snapshot {final int scene,pose,posture,kiss,expression,cross,restMotion,restFace;final boolean cycle,explicit,authority,fidget,restFacePinned,hold;Snapshot(EmbodiedScenePolicy p){hold=p.safeRestHold;restMotion=p.restMotion;restFace=p.restFace;restFacePinned=p.restFacePinned;scene=p.scene;pose=p.pose;posture=p.posture;kiss=p.kissType;expression=p.expression;cross=p.crossDirection;fidget=p.fidgetAt>=0;cycle=p.cycle;explicit=p.explicitExpression;authority=p.restAuthority;}void restore(EmbodiedScenePolicy p,long now){p.safeRestHold=hold;p.restMotion=restMotion;p.restFace=restFace;p.restFacePinned=restFacePinned;p.scene=scene;p.pose=pose;p.posture=posture;p.kissType=kiss;p.expression=expression;p.crossDirection=cross;p.cycle=cycle;p.explicitExpression=explicit;p.restAuthority=authority;p.at=now;p.fidgetAt=fidget?now:-1;}}
 void user(String text,long now){int repair=VisualRepairIntent.kind(text);if(repair!=0){if(pendingRepair==repair)return;pendingRepair=repair;if(repair==VisualRepairIntent.REPLAY&&lastVisual!=null)lastVisual.restore(this,now);else if(repair==VisualRepairIntent.UNDO&&previousVisual!=null){Snapshot current=new Snapshot(this);previousVisual.restore(this,now);if(restMotion==5||restMotion==7)at=now-6000;previousVisual=current;lastVisual=new Snapshot(this);}return;}
 pendingRepair=0;boolean visual=visualCommand(text)||!excluded(clean(text))&&(kissWords(clean(text))||has(clean(text),"よろめいて","ふらついて見せ"));Snapshot before=visual?new Snapshot(this):null;if(visual)safeRestHold=false;applyUser(text,now);if(visual&&(scene>=0||posture>=0)){if(!clean(text).equals(lastCommand)||now-lastCommandAt>3000)previousVisual=before;lastVisual=new Snapshot(this);lastCommand=clean(text);lastCommandAt=now;}}
 private void applyUser(String text,long now){String t=clean(text);int everyday=everydayCommand(t);if(everyday>=0){if(correctedRest()&&restMotion!=8&&restMotion!=11)return;scene=EVERYDAY;pose=everyday;at=now;cycle=false;return;}if(OffDutyPoseIntent.active(restMotion)&&OffDutyPoseIntent.shift(text)){at=now;return;}if(OffDutyPoseIntent.active(restMotion)&&OffDutyPoseIntent.sleepy(text)){restFace=10;restFacePinned=true;explicitExpression=true;return;}int comfort=ComfortPoseIntent.action(t);if(comfort>=0){scene=OVERHEAD;restMotion=8+comfort;restFace=comfort==7?10:0;restFacePinned=comfort==7;restAuthority=true;pose=0;posture=comfort==0||comfort==3?1:0;at=now;fidgetAt=-1;cycle=false;expression=-1;explicitExpression=false;return;}if(scene==OVERHEAD&&restMotion>=0&&has(t,"キス顔をやめて","キスをやめて")){restMotion=restFace=0;at=now;return;}long priorRestAt=at;int action=RestAnimationIntent.action(t);if(ComfortPoseIntent.active(restMotion)&&ComfortPoseIntent.unsupportedFace(action,restMotion))return;if(RestAnimationIntent.applies(t,scene==OVERHEAD)){scene=OVERHEAD;restAuthority=true;pose=action==4?5:0;posture=0;at=now;cycle=false;expression=-1;explicitExpression=true;if(action==13){restFacePinned=false;restFace=0;at=priorRestAt;fidgetAt=-1;}else if(action>=14&&action<=17){restFacePinned=true;restFace=action-8;if(restMotion==5||restMotion==7||ComfortPoseIntent.active(restMotion))at=priorRestAt;else restMotion=0;fidgetAt=-1;}else if(action==11){restMotion=7;fidgetAt=-1;}else if(action==12){restMotion=ComfortPoseIntent.active(restMotion)?restMotion:restMotion==5||restMotion==7?5:0;at=now-6000;fidgetAt=-1;}else if(action==9){restMotion=5;fidgetAt=-1;}else if(action==10){restMotion=restMotion==5||restMotion==6||restMotion==7?6:0;fidgetAt=-1;}else if(action<=4){restMotion=action==3&&(restMotion==5||restMotion==7)?7:action;if(action==3&&ShyFidgetMotion.request(t))fidgetAt=now;else fidgetAt=-1;}else{if(restMotion==5||restMotion==7||ComfortPoseIntent.active(restMotion)){at=priorRestAt;}else restMotion=0;restFace=action-4;restFacePinned=true;fidgetAt=-1;}return;}if(FullBodyAffectionCue.stop(t)||has(t,"離して","やめて","別の話","話題を変")){if(stoppingFidget(t,now)){fidgetAt=-1;return;}clearScene();return;}if(ShyFidgetMotion.request(t)){if(scene==OVERHEAD){pose=selected(now);cycle=false;at=now;}else if(scene!=RELAXED){scene=SHY_FIDGET;pose=1;at=now;}fidgetAt=now;return;}fidgetAt=-1;int rest=RestPoseIntent.kind(t);if(rest==RestPoseIntent.PROHIBIT_LIE){posture=1;clearScene();return;}if(RestPoseIntent.wantsLie(rest)&&!t.contains("上から")){scene=OVERHEAD;restMotion=restFace=0;restFacePinned=false;restAuthority=true;pose=0;posture=0;at=now;cycle=false;expression=-1;return;}if(rest==RestPoseIntent.RELAX&&(scene==RELAXED||scene==OVERHEAD)){restAuthority=true;at=now;return;}int face=PoisedMotionPolicy.expression(t);if((scene==RELAXED||scene==OVERHEAD)&&face>=0){expression=face;restFacePinned=face!=0;if(face==0)restFace=0;else if(face==1&&restMotion>=0)restFace=5;explicitExpression=true;if(restMotion!=5&&restMotion!=7)at=now;return;}int relaxed=PoisedMotionPolicy.relaxed(t,scene==RELAXED&&pose>=2||scene==OVERHEAD);if(relaxed>=0){scene=RELAXED;restAuthority=true;expression=-1;explicitExpression=false;pose=relaxed;posture=relaxed<2?1:0;at=now;cycle=false;return;}if(waveCommand(t)){if(scene==OVERHEAD){pose=5;cycle=false;at=now;return;}scene=WAVE;at=now;return;}int poised=PoisedMotionPolicy.command(t);if(poised>=0&&scene==OVERHEAD){pose=poised==3?2:poised==2?1:0;cycle=false;at=now;return;}if(poised>=0){scene=POISED;pose=poised;at=now;cycle=false;return;}if(legCommand(t)){posture=1;scene=LEG_CROSS;crossDirection=1-crossDirection;pose=crossDirection;at=now;cycle=false;return;}int p=postureCommand(t);if(p>=0){posture=p;clearScene();return;}if(excluded(t)){if(!stable())clearScene();return;}if(has(t,"私がよろめ","私はよろめ","私がふらつ")){clearScene();return;}
 if(has(t,"よろめいて","よろめく仕草","よろめく動作","ふらつく仕草","ふらついて見せ")){scene=STAGGER;at=now;cycle=false;return;}
 if(kissWords(t)){scene=KISS;kissType=KissGesturePolicy.type(t);at=now;cycle=false;return;}
 if(scene==KISS&&(KissGesturePolicy.strongFollowup(t)||KissGesturePolicy.normalFollowup(t)||has(t,"フレンチ","ディープ","突然","めろめろ","メロメロ"))){kissType=KissGesturePolicy.strongFollowup(t)?KissGesturePolicy.stronger(kissType):KissGesturePolicy.normalFollowup(t)?KissGesturePolicy.base(kissType):KissGesturePolicy.type(t);at=now;return;}
 if(has(t,"横たわ","横になって","寝転んで","寝ころんで","寝そべ","寝転が","仰向け","うつ伏せ","横向きで寝")){scene=OVERHEAD;at=now;pose=has(t,"右向き","右側")?3:has(t,"左向き","横向き")?2:has(t,"伸ば","伸び")?4:0;cycle=has(t,"いろんな","いろいろ","色々","何種類","順番に");return;}
 if(scene==OVERHEAD&&has(t,"次の姿勢","別の姿勢","違う姿勢","次のポーズ")){pose=(selected(now)+1)%8;at=now;cycle=false;return;}
 if(!stable()&&!has(t,"そのまま","続けて","ありがとう","いいね","うん","もう少し","もっと","かわいい","可愛い"))clearScene();}
 void answer(String text,FullBodyPoseCatalog.Kind kind,long now){pendingRepair=0;String t=clean(text);if(kind==FullBodyPoseCatalog.Kind.REFUSE&&ContactResponseBoundary.refused(text)||kind==FullBodyPoseCatalog.Kind.ANGER){boolean hold=correctedRest()&&restMotion!=8&&restMotion!=11;clearScene();safeRestHold=hold;lastVisual=previousVisual=null;return;}if((scene==RELAXED||scene==OVERHEAD)&&restAuthority){if(!explicitExpression)expression=kind==FullBodyPoseCatalog.Kind.SHY?2:kind==FullBodyPoseCatalog.Kind.JOY?1:kind==FullBodyPoseCatalog.Kind.CRY?5:kind==FullBodyPoseCatalog.Kind.WORRY?4:kind==FullBodyPoseCatalog.Kind.BREATH||kind==FullBodyPoseCatalog.Kind.PANT?6:0;return;}if(FullBodyAffectionCue.stop(t)||kind==FullBodyPoseCatalog.Kind.REFUSE||kind==FullBodyPoseCatalog.Kind.ANGER){if(stable()){fidgetAt=-1;clearScene();return;}clear();return;}if(scene==RELAXED&&!explicitExpression)expression=kind==FullBodyPoseCatalog.Kind.SHY?2:kind==FullBodyPoseCatalog.Kind.JOY?1:kind==FullBodyPoseCatalog.Kind.CRY?5:kind==FullBodyPoseCatalog.Kind.WORRY?4:kind==FullBodyPoseCatalog.Kind.BREATH||kind==FullBodyPoseCatalog.Kind.PANT?6:0;if(posture<0&&has(t,"座りました","腰を下ろしました","腰掛けました")&&!has(t,"あなた","ユーザー","彼女","友人","ません"))posture=1;}
 boolean allowed(FullBodyPoseCatalog.Kind k){if((scene==RELAXED||scene==OVERHEAD)&&restAuthority)return true;return scene==KISS?!FullBodyAffectionCue.negative(k):k!=FullBodyPoseCatalog.Kind.REFUSE&&k!=FullBodyPoseCatalog.Kind.ANGER;}
 int face(){return expression;}int posture(){return posture;}int base(int candidate){if(posture==1)return candidate>=0&&candidate<FullBodyPoseCatalog.ALL.length&&FullBodyMotionPolicy.isSeated(candidate)?candidate:168;if(posture==0)return candidate>=0&&candidate<FullBodyPoseCatalog.ALL.length&&!FullBodyMotionPolicy.isSeated(candidate)?candidate:4;return candidate;}
 int clip(long now,boolean quiet){return clip(now,quiet,false);}
 int clip(long now,boolean quiet,boolean seated){if(quiet||at<0||now<at||now-at>90000&&scene!=RELAXED&&!restAuthority)return -1;if(scene==SHY_FIDGET)return ShyFidgetMotion.active(fidgetAt,now)?seated?35:34:-1;if(scene==RELAXED&&ShyFidgetMotion.active(fidgetAt,now))return 36+pose;if(scene==RELAXED)return expression>=4?40+pose:expression>0?36+pose:pose<2?32:33;if(scene==EVERYDAY)return CharacterMotionTuning.time(now-at)<4600?FullBodyEverydayGesture.clip(posture==1||seated,pose):-1;if(scene==WAVE)return CharacterMotionTuning.time(now-at)<4600?(posture==1||seated?1:0):-1;if(scene==POISED)return seated?35:34;if(scene==LEG_CROSS)return 31;if(scene==STAGGER)return CharacterMotionTuning.time(now-at)<4800?26:-1;if(scene==KISS)return seated?30:27;if(scene==OVERHEAD)return 28+selected(now)/4;return -1;}
 void expression(int value){expression=Math.max(0,Math.min(6,value));explicitExpression=true;}
 int selected(long now){if(scene==RELAXED&&ShyFidgetMotion.active(fidgetAt,now))return ShyFidgetMotion.face(now-fidgetAt);if(scene==RELAXED&&expression>=4)return expression-4;if(scene==RELAXED&&expression>0)return expression;return cycle?Math.min(7,(int)Math.max(0,now-at)/4000):pose;}
 long local(long now){return Math.max(0,now-(ShyFidgetMotion.active(fidgetAt,now)?fidgetAt:at));}boolean moving(long now){return correctedRest()&&(RestAnimationTimeline.moving(restMotion(now),local(now))||ComfortPoseIntent.active(restMotion)&&local(now)<ComfortPoseGeometry.duration(restMotion-8)||local(now)<700)||ShyFidgetMotion.active(fidgetAt,now)|| scene==RELAXED&&local(now)<6000||(scene==WAVE||scene==EVERYDAY)&&CharacterMotionTuning.time(local(now))<4600||scene==POISED&&local(now)<7500||scene==LEG_CROSS&&local(now)<3400||scene==STAGGER&&CharacterMotionTuning.time(local(now))<4800||scene==KISS&&local(now)<4000||scene==OVERHEAD&&cycle&&local(now)<32000;}
 static int frame(int clip,long age,int selected){if(clip>=40)return selected%3;if(clip>=36)return selected%4;if(clip==32||clip==33)return selected%2;if(clip==34||clip==35)return PoisedMotionPolicy.frame(age,selected);if(clip==31){int frame=age<700?0:age<1600?1:2;return selected%2==1?frame:2-frame;}if(clip>=28&&clip!=30)return selected%4;if(clip==26)return age<650?0:age<1600?1:age<2700?2:3;if(clip==27||clip==30)return age<550?0:age<1500?1:2;return 0;}
